import { parseDocument, type Document } from 'yaml'

export type ConfigFormat = 'json' | 'yaml'

export interface ParsedConfig {
  doc: Document.Parsed
  format: ConfigFormat
  hadComments: boolean
  errors: string[]
}

export function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value)
}

/**
 * Turns the parsed tree into `path -> leaf value` (arrays and scalars are
 * leaves). The editor form is driven by this map.
 */
export function flatten(
  value: unknown,
  prefix = '',
  out: Record<string, unknown> = {}
): Record<string, unknown> {
  if (isPlainObject(value)) {
    const entries = Object.entries(value)
    if (entries.length === 0 && prefix) {
      // An empty object is kept as a leaf so it is not silently dropped.
      out[prefix] = {}
      return out
    }
    for (const [key, child] of entries) {
      flatten(child, prefix ? `${prefix}.${key}` : key, out)
    }
    return out
  }
  if (prefix) out[prefix] = value
  return out
}

export function unflatten(values: Record<string, unknown>): Record<string, unknown> {
  const root: Record<string, unknown> = {}
  for (const [path, value] of Object.entries(values)) {
    const parts = path.split('.')
    let cursor = root
    for (let i = 0; i < parts.length - 1; i += 1) {
      const key = parts[i] as string
      const next = cursor[key]
      if (!isPlainObject(next)) {
        cursor[key] = {}
      }
      cursor = cursor[key] as Record<string, unknown>
    }
    cursor[parts[parts.length - 1] as string] = value
  }
  return root
}

/**
 * Detects whether the file was strict JSON (what the plugin writes) or YAML
 * with comments and other YAML-only features.
 */
export function detectFormat(text: string): ConfigFormat {
  try {
    JSON.parse(text)
    return 'json'
  } catch {
    return 'yaml'
  }
}

/**
 * The plugin writes the file with `ConfigRenderOptions.comments(false)`, so a
 * generated file has no comments. Any `#` outside of a quoted string means a
 * human edited it and the comments must survive.
 */
export function hasComments(text: string): boolean {
  return text.split('\n').some(line => {
    const trimmed = line.trimStart()
    if (trimmed.startsWith('#')) return true
    return /(^|[^"'])\s#\s/.test(line)
  })
}

export function parseConfig(text: string): ParsedConfig {
  const doc = parseDocument(text)
  const errors = doc.errors.map(error => {
    const line = error.linePos?.[0]?.line
    const message = error.message.replace(/\s+at line \d+, column \d+.*$/, '')
    return line ? `Line ${line}: ${message}` : message
  })
  return {
    doc,
    format: detectFormat(text),
    hadComments: hasComments(text),
    errors,
  }
}
