<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { t } from '../../i18n'
import { fieldHelp, fieldLabel, type FieldDef } from './schema'

const props = defineProps<{
  field: FieldDef
  modelValue: unknown
  changed: boolean
  missing: boolean
  issue?: string
}>()

const emit = defineEmits<{ 'update:modelValue': [value: unknown] }>()

const revealed = ref(false)
const id = computed(() => `field-${props.field.path.replace(/\./g, '-')}`)

const isList = computed(() => props.field.type === 'list')
const isSecret = computed(() => props.field.type === 'secret')
const isNumber = computed(() => props.field.type === 'int' || props.field.type === 'double')

const items = computed<string[]>(() =>
  Array.isArray(props.modelValue) ? props.modelValue.map(item => String(item)) : []
)

const numberText = ref(String(props.modelValue ?? ''))
watch(
  () => props.modelValue,
  value => {
    numberText.value = String(value ?? '')
  }
)

const textValue = computed(() => (props.modelValue == null ? '' : String(props.modelValue)))

function setText(event: Event) {
  emit('update:modelValue', (event.target as HTMLInputElement).value)
}

function setNumber(event: Event) {
  const raw = (event.target as HTMLInputElement).value
  numberText.value = raw
  if (raw === '') return
  const parsed = Number(raw)
  if (!Number.isFinite(parsed)) return
  emit('update:modelValue', props.field.type === 'int' ? Math.trunc(parsed) : parsed)
}

function setItem(index: number, value: string) {
  const next = [...items.value]
  next[index] = value
  emit('update:modelValue', next)
}

function addItem() {
  emit('update:modelValue', [...items.value, ''])
}

function removeItem(index: number) {
  emit('update:modelValue', items.value.filter((_, i) => i !== index))
}

function generateSecret() {
  const bytes = new Uint8Array(32)
  crypto.getRandomValues(bytes)
  let binary = ''
  for (const byte of bytes) binary += String.fromCharCode(byte)
  emit('update:modelValue', btoa(binary))
}
</script>

<template>
  <div class="field" :class="{ changed, invalid: issue }">
    <div class="field-head">
      <label :for="id">{{ t(fieldLabel(field.path)) }}</label>
      <span class="path mono">{{ field.path }}</span>
      <span v-if="changed" class="badge warn">{{ t('config.changed') }}</span>
      <span v-if="missing" class="badge">{{ t('config.missing') }}</span>
    </div>

    <div v-if="field.type === 'bool'" class="control">
      <label class="switch">
        <input
          :id="id"
          type="checkbox"
          :checked="modelValue === true"
          @change="emit('update:modelValue', ($event.target as HTMLInputElement).checked)"
        />
        <span>{{ modelValue === true ? t('config.on') : t('config.off') }}</span>
      </label>
    </div>

    <div v-else-if="field.type === 'enum'" class="control">
      <select
        :id="id"
        :value="textValue"
        @change="emit('update:modelValue', ($event.target as HTMLSelectElement).value)"
      >
        <option v-for="option in field.enum" :key="option" :value="option">{{ option }}</option>
      </select>
    </div>

    <div v-else-if="isNumber" class="control">
      <input
        :id="id"
        type="number"
        :value="numberText"
        :step="field.type === 'double' ? '0.1' : '1'"
        @input="setNumber"
      />
      <span v-if="field.suffix" class="suffix">{{ field.suffix }}</span>
    </div>

    <div v-else-if="isSecret" class="control">
      <input :id="id" :type="revealed ? 'text' : 'password'" :value="textValue" @input="setText" />
      <button type="button" class="ghost" @click="revealed = !revealed">
        {{ revealed ? t('config.hide') : t('config.reveal') }}
      </button>
      <button v-if="field.path === 'auth.jwtSecret'" type="button" @click="generateSecret">
        {{ t('config.generate') }}
      </button>
    </div>

    <div v-else-if="isList" class="control list">
      <div v-for="(item, index) in items" :key="index" class="list-row">
        <input :id="index === 0 ? id : undefined" type="text" :value="item" @input="setItem(index, ($event.target as HTMLInputElement).value)" />
        <button type="button" class="ghost" @click="removeItem(index)" :aria-label="t('config.remove')">×</button>
      </div>
      <div class="list-actions">
        <button type="button" @click="addItem">{{ t('config.add') }}</button>
      </div>
      <p v-if="items.length === 0" class="muted small">{{ t('config.emptyList') }}</p>
    </div>

    <div v-else class="control">
      <input :id="id" type="text" :value="textValue" :class="{ mono: field.type === 'path' }" @input="setText" />
    </div>

    <p v-if="field.help" class="help muted small">{{ t(fieldHelp(field.path)) }}</p>
    <p v-if="issue" class="issue small">{{ issue }}</p>
  </div>
</template>

