import type { Document } from 'yaml'

export interface ExportInput {
  /** Working document: every changed value was already written into it. */
  doc: Document
  /** Untouched parse of the original text, used for byte ranges. */
  originalDoc: Document
  originalText: string
  values: Record<string, unknown>
  originalValues: Record<string, unknown>
  hadComments: boolean
  /** Paths that exist in `values` but not in the uploaded file. */
  added: readonly string[]
  /** Obsolete paths that were deleted from the working document. */
  removed: readonly string[]
}

export interface ExportResult {
  text: string
  /** True when comments could not be kept (missing keys were added). */
  commentsLost: boolean
}

interface Edit {
  start: number
  end: number
  text: string
}

const same = (a: unknown, b: unknown): boolean => JSON.stringify(a) === JSON.stringify(b)

/** Drops empty objects left behind after obsolete keys were deleted. */
function pruneEmpty(value: unknown): unknown {
  if (Array.isArray(value)) return value
  if (value === null || typeof value !== 'object') return value

  const out: Record<string, unknown> = {}
  for (const [key, child] of Object.entries(value)) {
    const pruned = pruneEmpty(child)
    if (pruned !== undefined) out[key] = pruned
  }
  return Object.keys(out).length > 0 ? out : undefined
}

/**
 * Replaces only the values that changed, using the byte ranges of the
 * original document. Comments, indentation and quoting stay exactly as they
 * were; only the edited scalars are rewritten.
 */
function patchText(
  text: string,
  originalDoc: Document,
  values: Record<string, unknown>,
  originalValues: Record<string, unknown>
): string {
  const edits: Edit[] = []

  for (const [path, value] of Object.entries(values)) {
    if (same(originalValues[path], value)) continue

    const node = originalDoc.getIn(path.split('.'), true) as
      | { range?: [number, number, number] }
      | undefined

    if (!node?.range) continue
    const [start, end] = node.range
    edits.push({ start, end, text: JSON.stringify(value) })
  }

  edits.sort((a, b) => b.start - a.start)

  let out = text
  for (const edit of edits) {
    out = out.slice(0, edit.start) + edit.text + out.slice(edit.end)
  }
  return out
}

/**
 * Public builds must stay readable by Typesafe Config. Plain JSON always is;
 * YAML is only safe with flow collections, which is exactly what the patched
 * output keeps because it only swaps scalar values (and JSON-encodes lists).
 */
export function exportConfig(input: ExportInput): ExportResult {
  const { doc, originalDoc, originalText, values, originalValues, hadComments, added, removed } = input
  const plain = pruneEmpty(doc.toJS()) ?? {}
  const json = `${JSON.stringify(plain, null, 4)}\n`

  if (!hadComments) {
    return { text: json, commentsLost: false }
  }

  // Adding or removing keys means new or missing lines, which cannot be
  // patched into the original text without guessing where they belong.
  // Fall back to JSON and say so.
  if (added.length > 0 || removed.length > 0) {
    return { text: json, commentsLost: hadComments }
  }

  return { text: patchText(originalText, originalDoc, values, originalValues), commentsLost: false }
}
