<script setup lang="ts">
import { computed, ref, shallowRef, watch } from 'vue'
import type { Document } from 'yaml'
import { t } from '../../i18n'
import ConfigField from './ConfigField.vue'
import { exportConfig, type ExportResult } from './export'
import { flatten, parseConfig, type ConfigFormat } from './parse'
import { SAMPLE_CONFIG } from './sample'
import { FIELDS, FIELD_BY_PATH, GROUPS, OBSOLETE_PATHS, type GroupId } from './schema'
import { countByLevel, validate } from './validate'

const fileName = ref('config.yml')
const originalText = ref('')
const originalDoc = shallowRef<Document | null>(null)
const doc = shallowRef<Document | null>(null)
const values = ref<Record<string, unknown>>({})
const originalValues = ref<Record<string, unknown>>({})
const removedPaths = ref<string[]>([])
const hadComments = ref(false)
const format = ref<ConfigFormat>('json')
const parseError = ref('')
const onlyChanged = ref(false)
const fillMissing = ref(false)
const dragging = ref(false)
const copied = ref(false)

const loaded = computed(() => doc.value !== null)

const same = (a: unknown, b: unknown) => JSON.stringify(a) === JSON.stringify(b)

const isMissing = (path: string) => !Object.prototype.hasOwnProperty.call(originalValues.value, path)

const changedPaths = computed(() =>
  FIELDS.map(field => field.path).filter(path => !same(values.value[path], originalValues.value[path]))
)

const unknownPaths = computed(() =>
  Object.keys(values.value).filter(path => !FIELD_BY_PATH.has(path))
)

const issues = computed(() => validate(values.value))
const counts = computed(() => countByLevel(issues.value))

const preview = computed<ExportResult | null>(() => {
  if (!doc.value) return null
  const working = doc.value.clone()
  const added: string[] = []

  for (const path of removedPaths.value) {
    working.deleteIn(path.split('.'))
  }

  for (const [path, value] of Object.entries(values.value)) {
    const current = working.getIn(path.split('.'))
    if (same(current, value)) continue
    working.setIn(path.split('.'), value)
    if (isMissing(path)) added.push(path)
  }

  return exportConfig({
    doc: working,
    originalDoc: doc.value,
    originalText: originalText.value,
    values: values.value,
    originalValues: originalValues.value,
    hadComments: hadComments.value,
    added,
    removed: removedPaths.value,
  })
})

const formats = computed(() => ({
  label: format.value === 'json' ? 'JSON' : 'YAML',
}))

function fieldValue(path: string): unknown {
  if (Object.prototype.hasOwnProperty.call(values.value, path)) return values.value[path]
  return FIELDS.find(field => field.path === path)?.default
}

function setField(path: string, value: unknown) {
  values.value = { ...values.value, [path]: value }
}

function issueFor(path: string): string | undefined {
  return issues.value.find(issue => issue.path === path && issue.level === 'error')?.message
}

function fieldsFor(group: GroupId) {
  const fields = FIELDS.filter(field => field.group === group)
  if (!onlyChanged.value) return fields
  return fields.filter(field => !same(values.value[field.path], originalValues.value[field.path]))
}

function loadText(text: string, name: string) {
  const parsed = parseConfig(text)
  if (parsed.errors.length > 0) {
    parseError.value = parsed.errors.join(' · ')
    return
  }

  const flat = flatten(parsed.doc.toJS())
  const obsolete = Object.keys(flat).filter(path => OBSOLETE_PATHS.has(path))
  const current = { ...flat }
  for (const path of obsolete) delete current[path]

  parseError.value = ''
  fileName.value = name
  format.value = parsed.format
  hadComments.value = parsed.hadComments
  originalText.value = text
  originalDoc.value = parsed.doc
  doc.value = parsed.doc
  originalValues.value = current
  values.value = { ...current }
  removedPaths.value = obsolete
  onlyChanged.value = false
  fillMissing.value = false
}

async function onPick(event: Event) {
  const file = (event.target as HTMLInputElement).files?.[0]
  if (file) loadText(await file.text(), file.name)
}

async function onDrop(event: DragEvent) {
  dragging.value = false
  const file = event.dataTransfer?.files?.[0]
  if (file) loadText(await file.text(), file.name)
}

function loadSample() {
  loadText(SAMPLE_CONFIG, 'config.yml')
}

function reset() {
  fileName.value = 'config.yml'
  originalText.value = ''
  originalDoc.value = null
  doc.value = null
  values.value = {}
  originalValues.value = {}
  removedPaths.value = []
  hadComments.value = false
  format.value = 'json'
  parseError.value = ''
  onlyChanged.value = false
  fillMissing.value = false
}

function download() {
  const text = preview.value?.text
  if (!text) return
  const blob = new Blob([text], { type: 'application/yaml' })
  const url = URL.createObjectURL(blob)
  const link = document.createElement('a')
  link.href = url
  link.download = fileName.value.endsWith('.yml') || fileName.value.endsWith('.yaml')
    ? fileName.value
    : `${fileName.value}.yml`
  link.click()
  URL.revokeObjectURL(url)
}

async function copy() {
  const text = preview.value?.text
  if (!text) return
  await navigator.clipboard.writeText(text)
  copied.value = true
  setTimeout(() => {
    copied.value = false
  }, 1500)
}

function display(value: unknown): string {
  if (value === undefined) return '—'
  return JSON.stringify(value)
}

// Turning the option on materialises every missing schema key with its
// default. Turning it off drops the ones the user did not touch.
watch(fillMissing, enabled => {
  if (!loaded.value) return
  const next = { ...values.value }
  for (const field of FIELDS) {
    if (!isMissing(field.path)) continue
    if (enabled) {
      next[field.path] = Array.isArray(field.default) ? [...field.default] : field.default
    } else if (same(next[field.path], field.default)) {
      delete next[field.path]
    }
  }
  values.value = next
})
</script>

<template>
  <div class="stack">
    <header>
      <h1>{{ t('config.title') }}</h1>
      <p class="muted">{{ t('config.lead') }}</p>
    </header>

    <section
      class="card load"
      :class="{ dragging }"
      @dragover.prevent="dragging = true"
      @dragleave.prevent="dragging = false"
      @drop.prevent="onDrop"
    >
      <h2>{{ t('config.load.title') }}</h2>
      <p class="muted">{{ t('config.load.hint') }}</p>

      <div class="row">
        <label class="button primary">
          {{ t('config.load.choose') }}
          <input type="file" accept=".yml,.yaml,.json,text/plain" hidden @change="onPick" />
        </label>
        <button type="button" @click="loadSample">{{ t('config.load.sample') }}</button>
        <span v-if="loaded" class="badge">{{ formats.label }}</span>
        <span v-if="loaded" class="mono muted file">{{ fileName }}</span>
        <button v-if="loaded" type="button" class="ghost" @click="reset">
          {{ t('config.reset') }}
        </button>
      </div>

      <p v-if="parseError" class="error-text">{{ t('config.parse.error') }}: {{ parseError }}</p>
      <p v-else-if="!loaded" class="muted small">{{ t('config.noFile') }}</p>
    </section>

    <template v-if="loaded">
      <div class="row stats">
        <span class="badge">{{ t('config.stat.changes', { n: changedPaths.length }) }}</span>
        <span v-if="unknownPaths.length" class="badge warn">
          {{ t('config.stat.unknown', { n: unknownPaths.length }) }}
        </span>
        <span v-if="removedPaths.length" class="badge">
          {{ t('config.stat.obsolete', { n: removedPaths.length }) }}
        </span>
        <span v-if="counts.error" class="badge error">
          {{ t('config.stat.errors', { n: counts.error }) }}
        </span>
        <span v-if="counts.warn" class="badge warn">
          {{ t('config.stat.warnings', { n: counts.warn }) }}
        </span>
        <span v-if="hadComments" class="badge">{{ t('config.comments') }}</span>

        <label class="toggle">
          <input v-model="onlyChanged" type="checkbox" />
          {{ t('config.onlyChanged') }}
        </label>
        <label class="toggle">
          <input v-model="fillMissing" type="checkbox" />
          {{ t('config.fillMissing') }}
        </label>
      </div>

      <div class="layout">
        <div class="stack">
          <section v-for="group in GROUPS" :key="group" class="card">
            <template v-if="fieldsFor(group).length">
              <h2>{{ t(`config.group.${group}`) }}</h2>
              <ConfigField
                v-for="field in fieldsFor(group)"
                :key="field.path"
                :field="field"
                :model-value="fieldValue(field.path)"
                :changed="!same(values[field.path], originalValues[field.path])"
                :missing="isMissing(field.path)"
                :issue="issueFor(field.path)"
                @update:model-value="setField(field.path, $event)"
              />
            </template>
          </section>

          <section v-if="removedPaths.length" class="card">
            <h2>{{ t('config.obsolete.title') }}</h2>
            <p class="muted small">{{ t('config.obsolete.note') }}</p>
            <ul class="unknown mono">
              <li v-for="path in removedPaths" :key="path">{{ path }}</li>
            </ul>
          </section>

          <section class="card">
            <h2>{{ t('config.unknown.title') }}</h2>
            <p class="muted small">{{ t('config.unknown.note') }}</p>
            <p v-if="unknownPaths.length === 0" class="muted small">
              {{ t('config.unknown.empty') }}
            </p>
            <ul v-else class="unknown mono">
              <li v-for="path in unknownPaths" :key="path">
                <span class="muted">{{ path }}</span> = {{ display(values[path]) }}
              </li>
            </ul>
          </section>
        </div>

        <aside class="stack side">
          <section class="card">
            <h2>{{ t('config.issues.title') }}</h2>
            <p v-if="issues.length === 0" class="muted small">{{ t('config.issues.none') }}</p>
            <ul v-else class="issues">
              <li v-for="(issue, index) in issues" :key="index" :class="issue.level">
                <span class="mono path">{{ issue.path }}</span>
                <span>{{ issue.message }}</span>
              </li>
            </ul>
          </section>

          <section class="card">
            <h2>{{ t('config.changes.title') }}</h2>
            <p v-if="changedPaths.length === 0" class="muted small">
              {{ t('config.changes.none') }}
            </p>
            <table v-else class="changes">
              <tbody>
                <tr v-for="path in changedPaths" :key="path">
                  <th class="mono">{{ path }}</th>
                  <td>
                    <span class="muted old">{{ display(originalValues[path]) }}</span>
                    <span aria-hidden="true"> → </span>
                    <span class="new">{{ display(values[path]) }}</span>
                  </td>
                </tr>
              </tbody>
            </table>
          </section>
        </aside>
      </div>

      <section class="card">
        <h2>{{ t('config.preview.title') }}</h2>
        <p class="muted small">{{ t('config.preview.hint') }}</p>
        <p v-if="preview?.commentsLost" class="warn-text">{{ t('config.commentsLost') }}</p>
        <pre>{{ preview?.text }}</pre>
        <div class="row actions">
          <button type="button" class="primary" @click="download">
            {{ t('config.download') }}
          </button>
          <button type="button" @click="copy">
            {{ copied ? t('config.copied') : t('config.copy') }}
          </button>
        </div>
      </section>
    </template>
  </div>
</template>

