/**
 * Field registry for config.yml.
 *
 * Source of truth is `PluginConfig` in the plugin: only keys that are actually
 * read at runtime are listed here. The file is written by Typesafe Config, so
 * it is JSON-shaped even though it is called .yml.
 *
 * `OBSOLETE_PATHS` are keys from older releases that the plugin no longer
 * reads. The editor removes them on load so the downloaded file only contains
 * options that still do something. Truly unknown keys are never touched.
 */

export type FieldType = 'bool' | 'int' | 'double' | 'string' | 'list' | 'enum' | 'secret' | 'path'

export const GROUPS = ['general', 'web', 'peerjs', 'auth', 'turn', 'tls'] as const

export type GroupId = (typeof GROUPS)[number]

export interface FieldDef {
  path: string
  type: FieldType
  group: GroupId
  default: unknown
  enum?: readonly string[]
  /** Set for fields that carry a `help.<path>` entry. */
  help?: boolean
  /** Short hint next to the input, e.g. the unit. */
  suffix?: string
}

export const FIELDS: readonly FieldDef[] = [
  { path: 'debug', type: 'bool', group: 'general', default: false },
  { path: 'configDir', type: 'path', group: 'general', default: '.' },
  { path: 'development', type: 'bool', group: 'general', default: true, help: true },

  { path: 'web.host', type: 'string', group: 'web', default: '0.0.0.0', help: true },
  { path: 'web.port', type: 'int', group: 'web', default: 24454, help: true },
  { path: 'web.tlsTerminatedExternally', type: 'bool', group: 'web', default: false, help: true },

  { path: 'peerjs.enabled', type: 'bool', group: 'peerjs', default: false, help: true },
  { path: 'peerjs.scheme', type: 'enum', group: 'peerjs', default: 'wss', enum: ['wss', 'ws'] },
  { path: 'peerjs.host', type: 'string', group: 'peerjs', default: '0.peerjs.com' },
  { path: 'peerjs.port', type: 'int', group: 'peerjs', default: 443 },
  { path: 'peerjs.path', type: 'string', group: 'peerjs', default: '/' },
  { path: 'peerjs.key', type: 'string', group: 'peerjs', default: 'peerjs' },
  { path: 'peerjs.token', type: 'string', group: 'peerjs', default: '', help: true },

  { path: 'auth.codeTtlSeconds', type: 'int', group: 'auth', default: 300, suffix: 's' },
  { path: 'auth.jwtTtlSeconds', type: 'int', group: 'auth', default: 86400, suffix: 's' },
  { path: 'auth.jwtSecret', type: 'secret', group: 'auth', default: '', help: true },

  { path: 'turn.enabled', type: 'bool', group: 'turn', default: false },
  { path: 'turn.urls', type: 'list', group: 'turn', default: [], help: true },
  { path: 'turn.username', type: 'string', group: 'turn', default: '' },
  { path: 'turn.credential', type: 'secret', group: 'turn', default: '' },

  { path: 'tls.keystorePassword', type: 'secret', group: 'tls', default: '', help: true },
]

/**
 * Keys that older plugin versions wrote but no code reads anymore. They are
 * dropped on load; the plugin would ignore them anyway.
 */
export const OBSOLETE_PATHS: ReadonlySet<string> = new Set([
  'language',
  'mode',
  'resourcePackAutoHost',
  'resourcePackSha1',
  'resourcePackUrl',
  'web.enabled',
  'web.staticDir',
  'web.corsAllowedOrigins',
  'web.portShareWithSvc',
  'web.maxParticipants',
  'webrtc.port',
  'svc.enabled',
  'svc.simulateMicrophone',
  'svc.mirrorGroups',
  'svc.positionalAudio',
  'svc.showWebPlayersInSvc',
  'auth.joinLinkBaseUrl',
  'distribution.bundleWebClient',
  'logging.level',
  'logging.logSvcPackets',
  'logging.logWebsocketMessages',
  'private.enabled',
  'webhooks.enabled',
  'webhooks.url',
  'webhooks.events',
  'webhooks.secret',
  'audio.minDistance',
  'audio.maxDistance',
])

export const FIELD_BY_PATH: ReadonlyMap<string, FieldDef> = new Map(
  FIELDS.map(field => [field.path, field])
)

export const KNOWN_PATHS: ReadonlySet<string> = new Set(FIELDS.map(field => field.path))

/** A fresh object with every default, always deep-copied. */
export function defaultValues(): Record<string, unknown> {
  const out: Record<string, unknown> = {}
  for (const field of FIELDS) {
    out[field.path] = Array.isArray(field.default) ? [...field.default] : field.default
  }
  return out
}

export function fieldLabel(path: string): string {
  return `field.${path}`
}

export function fieldHelp(path: string): string {
  return `help.${path}`
}
