import { parseConfig } from './parse'

/**
 * The plugin writes this on first start (see `buildDefaultConfig()`), with
 * PeerJS off because that is the shipped default. Only options that the
 * plugin actually reads are part of the file.
 */
const SAMPLE_OBJECT = {
  auth: {
    codeTtlSeconds: 300,
    jwtSecret: '',
    jwtTtlSeconds: 86400,
  },
  configDir: '.',
  debug: false,
  development: true,
  peerjs: {
    enabled: false,
    host: '0.peerjs.com',
    key: 'peerjs',
    path: '/',
    port: 443,
    scheme: 'wss',
    token: '',
  },
  tls: { keystorePassword: '' },
  turn: { credential: '', enabled: false, urls: [], username: '' },
  web: {
    host: '0.0.0.0',
    port: 24454,
    tlsTerminatedExternally: false,
  },
}

export const SAMPLE_CONFIG = `${JSON.stringify(SAMPLE_OBJECT, null, 4)}\n`

/** Used by tests: the sample must describe exactly the known schema. */
export function sampleValues(): Record<string, unknown> {
  return parseConfig(SAMPLE_CONFIG).doc.toJS() as Record<string, unknown>
}
