import { t } from '../../i18n'
import { defaultValues } from './schema'

export type IssueLevel = 'error' | 'warn' | 'info'

export interface Issue {
  level: IssueLevel
  path: string
  message: string
}

/**
 * Mirrors `PluginConfig.validate()`: only rules that the plugin itself
 * enforces, plus a hint for the empty JWT secret.
 */
export function validate(values: Record<string, unknown>): Issue[] {
  const v: Record<string, unknown> = { ...defaultValues(), ...values }
  const issues: Issue[] = []

  const bool = (path: string) => v[path] === true
  const num = (path: string) => Number(v[path])
  const str = (path: string) => String(v[path] ?? '').trim()
  const list = (path: string): unknown[] => (Array.isArray(v[path]) ? (v[path] as unknown[]) : [])

  const port = (path: string) => {
    const value = num(path)
    if (!Number.isInteger(value) || value < 1 || value > 65535) {
      issues.push({
        level: 'error',
        path,
        message: t('validation.portRange', { path, value: String(v[path] ?? '') }),
      })
    }
  }

  port('web.port')

  if (bool('peerjs.enabled')) {
    port('peerjs.port')
    if (!str('peerjs.host')) {
      issues.push({ level: 'error', path: 'peerjs.host', message: t('validation.peerjsHost') })
    }
  }

  if (bool('turn.enabled')) {
    if (list('turn.urls').length === 0) {
      issues.push({ level: 'error', path: 'turn.urls', message: t('validation.turnUrls') })
    }
    if (!str('turn.username') || !str('turn.credential')) {
      issues.push({ level: 'error', path: 'turn.username', message: t('validation.turnCreds') })
    }
  }

  if (!str('auth.jwtSecret')) {
    issues.push({ level: 'warn', path: 'auth.jwtSecret', message: t('validation.jwtEmpty') })
  }

  if (str('peerjs.token') && !bool('peerjs.enabled')) {
    issues.push({ level: 'info', path: 'peerjs.token', message: t('validation.peerjsToken') })
  }

  return issues
}

export function countByLevel(issues: readonly Issue[]): Record<IssueLevel, number> {
  const counts: Record<IssueLevel, number> = { error: 0, warn: 0, info: 0 }
  for (const issue of issues) counts[issue.level] += 1
  return counts
}
